#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

struct Child {
    int v, d, p;
    int original_index;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<Child> children(n);
    for (int i = 0; i < n; ++i) {
        cin >> children[i].v >> children[i].d >> children[i].p;
        children[i].original_index = i + 1;
    }

    vector<int> result;
    queue<int> q;

    for (int i = 0; i < n; ++i) {
        q.push(i);
    }

    while (!q.empty()) {
        int current = q.front();
        q.pop();

        // Treat the current child
        result.push_back(children[current].original_index);

        int cry_volume = children[current].v;
        int len = q.size();
        for (int i = 0; i < min(len, cry_volume); ++i) {
            int idx = q.front();
            children[idx].p -= (cry_volume - i);
            q.pop();
            if (children[idx].p < 0) {
                // This child starts crying and leaves
                int dj = children[idx].d;
                // Add back the children that were removed from the queue
                q.push(idx);
                // Apply dj to all children after this one
                int size = q.size();
                for (int j = 0; j < size; ++j) {
                    int next_idx = q.front();
                    children[next_idx].p -= dj;
                    q.pop();
                    if (children[next_idx].p < 0) {
                        // Chain reaction
                        q.push(next_idx);
                    }
                }
                // Reinsert the children that were processed in this loop
                for (int j = 0; j < size; ++j) {
                    q.push(next_idx);
                }
            } else {
                q.push(idx);
            }
        }
    }

    cout << result.size() << '\n';
    for (int num : result) {
        cout << num << ' ';
    }
    cout << '\n';

    return 0;
}

