    cin >> n;
    vector<Child> queue;
    for (int i = 1; i <= n; ++i) {
        int vi, di, pi;
        cin >> vi >> di >> pi;
        queue.push_back({vi, di, pi, i});
    }

    vector<int> result;

    while (!queue.empty()) {
        // Treat the first child
        Child current = queue[0];
        result.push_back(current.original_index);

        // Apply vi effect to the remaining children
        int vi = current.vi;
        int m = queue.size();
        for (int j = 0; j < m - 1; ++j) {
            if (j < vi) {
                queue[j + 1].confidence -= (vi - j);
            }
        }

        // Remove the current child from the queue
        queue.erase(queue.begin());

        // Process children with confidence < 0
