            int idx = -1;
            for (int i = 0; i < queue.size(); ++i) {
                if (queue[i].confidence < 0) {
                    idx = i;
                    break;
                }
            }
            if (idx == -1) break;

            // Remove the child at idx
            Child removed = queue[idx];
            queue.erase(queue.begin() + idx);
            int dj = removed.di;

            // Apply dj to children after idx
            for (int j = idx; j < queue.size(); ++j) {
                queue[j].confidence -= dj;
            }
        }
    }

    cout << result.size() << endl;
    for (int num : result) {
