using namespace std;

const int MOD = 1000000007;

long long mod_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            res = (res * base) % mod;
        base = (base * base) % mod;
        exp = exp / 2;
    }
    return res;
}

void factor(int n, vector<pair<int, int>>& factors) {
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            int cnt = 0;
            while (n % i == 0) {
                cnt++;
                n /= i;
            }
            factors.push_back({i, cnt});
        }
    }
    if (n > 1) {
        factors.push_back({n, 1});
    }
}

void generate_divisors(const vector<pair<int, int>>& factors, int current, int index, vector<int>& divisors) {
    if (index == factors.size()) {
        divisors.push_back(current);
        return;
    }
    int prime = factors[index].first;
    int max_exp = factors[index].second;
    int p_power = 1;
    for (int i = 0; i <= max_exp; ++i) {
        generate_divisors(factors, current * p_power, index + 1, divisors);
        p_power *= prime;
    }
}

int multiplicative_order(int m, int p) {
    int phi = p - 1;
    vector<pair<int, int>> factors;
    factor(phi, factors);
    vector<int> divisors;
    generate_divisors(factors, 1, 0, divisors);
    sort(divisors.begin(), divisors.end());
    for (int d : divisors) {
        if (mod_pow(m, d, p) == 1) {
            return d;
        }
    }
    return phi;  // This line is theoretically unreachable
}

