        cout << mod_pow(p, exponent, MOD) << endl;
    } else if (m == 1) {
        int exponent = p - 1;
        cout << mod_pow(p, exponent, MOD) << endl;
    } else {
        int d = multiplicative_order(m, p);
        int exponent = (p - 1) / d;
        cout << mod_pow(p, exponent, MOD) << endl;
    }
    return 0;
}

