};

bool compareInterval(const Interval& a, const Interval& b) {
    return a.start < b.start || (a.start == b.start && a.end < b.end);
}

int64_t mergeIntervals(const vector<Interval>& intervals) {
    if (intervals.empty()) return 0;

    sort(intervals.begin(), intervals.end(), compareInterval);

    int64_t total = intervals[0].end - intervals[0].start + 1;
    int64_t prevEnd = intervals[0].end;

    for (size_t i = 1; i < intervals.size(); ++i) {
        if (intervals[i].start > prevEnd) {
            total += intervals[i].end - intervals[i].start + 1;
            prevEnd = intervals[i].end;
        } else {
            prevEnd = max(prevEnd, intervals[i].end);
        }
    }

    return total;
}

