            if (c == '1') {
                one_count++;
            }
        }
        if (one_count > 1) {
            is_beautiful = false;
        }
        if (!is_beautiful) {
            non_beautiful_index = i;
            break;
        }
    }

    if (non_beautiful_index == -1) {
        // All are beautiful, so at least one is 0
        cout << 0;
        return 0;
    }

    // Convert all numbers to integers, except the non-beautiful one
    // We need to compute the product, but keep track of zeros
    long long product = 1;
    bool has_zero = false;
    for (int i = 0; i < n; ++i) {
        if (i == non_beautiful_index) {
            // Convert to long long
            long long val = stoll(a[i]);
            product *= val;
        } else {
            // Check if it's zero
            if (a[i] == "0") {
                has_zero = true;
            } else {
                // It's a beautiful number with one '1' and rest '0's
                // So it's a power of 10, and we can multiply with product
