    while (ss >> s) {
        nums.push_back(s);
    }
    // Check if any is zero
    for (const string& num : nums) {
        if (num == "0") {
            cout << 0 << endl;
            return 0;
        }
    }
    // Find the non-beautiful number
    string non_beautiful;
    bool found = false;
    for (const string& num : nums) {
        if (!is_beautiful(num)) {
            non_beautiful = num;
            found = true;
            break;
        }
    }
    if (!found) {
        // All are beautiful
        int sum = 0;
        for (const string& num : nums) {
            sum += (num.length() - 1);
        }
        cout << "1" << string(sum, '0') << endl;
        return 0;
    }
    // Compute sum
    int sum = 0;
    for (const string& num : nums) {
        if (num != non_beautiful) {
            sum += (num.length() - 1);
        }
    }
    // Output
