#include <bits/stdc++.h>
using namespace std;

int find_any(int l, int r, int x, const vector<int>& a) {
    if (l > r) return -1;
    int mid = (l + r) / 2;
    if (a[mid - 1] != x) {
        return mid;
    }
    int left_res = find_any(l, mid - 1, x, a);
    if (left_res != -1) return left_res;
    return find_any(mid + 1, r, x, a);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    unordered_map<int, vector<int>> pos;
    for (int i = 0; i < n; ++i) {
        pos[a[i]].push_back(i + 1); // 1-based index
    }

    for (int q = 0; q < m; ++q) {
        int l, r, x;
        cin >> l >> r >> x;
        auto it = pos.find(x);
        vector<int>* v = (it != pos.end()) ? &it->second : nullptr;
        int count_x = 0;
        if (v) {
            auto left = lower_bound(v->begin(), v->end(), l);
            auto right_b = upper_bound(v->begin(), v->end(), r);
            count_x = right_b - left;
        } else {
            count_x = 0;
        }

        if (count_x == (r - l + 1)) {
            cout << -1 << '\n';
        } else {
            if (a[l - 1] != x) {
                cout << l << '\n';
            } else if (a[r - 1] != x) {
                cout << r << '\n';
            } else {
                int p = find_any(l, r, x, a);
                cout << p << '\n';
            }
        }
    }
    return 0;
}

