#include <bits/stdc++.h>
using namespace std;

struct SegmentTreeNode {
    int l, r;
    int value;
    bool same;
    SegmentTreeNode *left, *right;
};

SegmentTreeNode* build_tree(int l, int r, vector<int>& a) {
    SegmentTreeNode* node = new SegmentTreeNode();
    node->l = l;
    node->r = r;
    if (l == r) {
        node->same = true;
        node->value = a[l];
        node->left = node->right = nullptr;
        return node;
    }
    int mid = (l + r) / 2;
    node->left = build_tree(l, mid, a);
    node->right = build_tree(mid + 1, r, a);
    if (node->left->same && node->right->same && node->left->value == node->right->value) {
        node->same = true;
        node->value = node->left->value;
    } else {
        node->same = false;
        node->value = 0; // irrelevant
    }
    return node;
}

int query_tree(SegmentTreeNode* node, int l, int r, int xi) {
    if (node->r < l || node->l > r) {
        return -1;
    }
    if (l <= node->l && node->r <= r) {
        if (node->same) {
            if (node->value != xi) {
                return node->l;
            } else {
                return -1;
            }
        } else {
            int left_res = query_tree(node->left, l, r, xi);
            if (left_res != -1) return left_res;
            return query_tree(node->right, l, r, xi);
        }
    } else {
        int left_res = query_tree(node->left, l, r, xi);
        if (left_res != -1) return left_res;
        return query_tree(node->right, l, r, xi);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<int> a(n + 1); // 1-based indexing
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    SegmentTreeNode* root = build_tree(1, n, a);
    for (int i = 0; i < m; ++i) {
        int li, ri, xi;
        cin >> li >> ri >> xi;
        int res = query_tree(root, li, ri, xi);
        cout << (res == -1 ? -1 : res) << endl;
    }
    return 0;
}

