#include <iostream>
#include <vector>
#include <iomanip>
#include <cmath>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<double> max_prob(n);
    vector<double> min_prob(n);
    for (int i = 0; i < n; ++i) {
        cin >> max_prob[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> min_prob[i];
    }

    vector<double> pa(n, 0.0);
    vector<double> pb(n, 0.0);

    // For each i, the probability that a = i is:
    // P(max = i) - P(min = i) + P(min = i-1) where i > 1, but considering all combinations
    // Another approach is to calculate for each i, the total contribution to the max and min.

    // Let's compute the probabilities for each dice
    for (int i = 0; i < n; ++i) {
        double p_max_i = max_prob[i];
        double p_min_i = min_prob[i];
        pa[i] = p_max_i - p_min_i;
        if (i > 0) {
            pa[i] += min_prob[i - 1];
        }
    }

    // We need to compute pb from max and min as well
    for (int i = 0; i < n; ++i) {
        double p_max_i = max_prob[i];
        double p_min_i = min_prob[i];
        pb[i] = p_max_i - p_min_i;
        if (i > 0) {
            pb[i] += min_prob[i - 1];
        }
    }

    // Normalize the probabilities for pa and pb
    double sum_pa = 0.0;
    double sum_pb = 0.0;
    for (int i = 0; i < n; ++i) {
        sum_pa += pa[i];
        sum_pb += pb[i];
    }
    for (int i = 0; i < n; ++i) {
        pa[i] /= sum_pa;
        pb[i] /= sum_pb;
    }

    // Output
    for (int i = 0; i < n; ++i) {
        cout << fixed << setprecision(8) << pa[i] << " ";
    }
    cout << endl;
    for (int i = 0; i < n; ++i) {
        cout << fixed << setprecision(8) << pb[i] << " ";
    }
    cout << endl;

    return 0;
}

