    cin >> n >> k;

    long long max_mess = 0;

    // Maximum possible messiness is n*(n-1)/2
    long long total_max = n * (n - 1) / 2;

    // Each swap can contribute at most (2 * (i) - 1) to the messiness
    // For example, swapping 1 and n contributes (n-1) + (n-2) = 2n - 3
    // So we greedily apply the swaps contributing the most
    long long current = n - 1;
    long long swaps = 0;
    long long mess = 0;

    while (k > 0 && swaps < n / 2) {
        mess += current;
        current -= 2;
        k--;
        swaps++;
    }

    // If there are remaining swaps, each can contribute at least 1
    mess += min(k, n - 2 * swaps) * 1;

    cout << min(mess, total_max) << endl;

    return 0;
}

