#include <string>
#include <sstream>
#include <iomanip>
#include <cmath>

using namespace std;

unordered_map<string, int> memo;

int get_year(const string& s) {
    if (memo.find(s) != memo.end()) {
        return memo[s];
    }

    int len_s = s.length();
    int s_num = stoi(s);
    int mod_val = 1;
    for (int i = 0; i < len_s; ++i) {
        mod_val *= 10;
    }

    int r = 1989 % mod_val;
    int Y_candidate;
    if (s_num >= r) {
        Y_candidate = 1989 + (s_num - r);
    } else {
        Y_candidate = 1989 + (mod_val - r + s_num);
    }

    while (true) {
        bool valid = true;
        for (int k = 1; k < len_s; ++k) {
            int mod_k = 1;
            for (int i = 0; i < k; ++i) {
                mod_k *= 10;
            }
            int s_k_num = Y_candidate % mod_k;
            ostringstream oss;
            oss << setw(k) << setfill('0') << s_k_num;
            string s_k_str = oss.str();
            int Y_k = get_year(s_k_str);
            if (Y_k >= Y_candidate) {
                valid = false;
                break;
            }
        }
        if (valid) {
            memo[s] = Y_candidate;
            return Y_candidate;
        } else {
            Y_candidate += mod_val;
        }
    }
}

