map<string, int> memo;

int find_year(const string& s) {
    if (memo.count(s)) return memo[s];

    int k = s.length();
    long long s_num = stoll(s);

    // Compute base = 10^k
    long long base = 1;
    for (int i = 0; i < k; ++i) base *= 10;

    int start_year = 1989;
    long long r = start_year % base;
    long long required_remainder = s_num;
    long long delta = (required_remainder - r + base) % base;
    long long Y_candidate = start_year + delta;

    while (true) {
        bool valid = true;
        for (int l = 1; l < k; ++l) {
            // compute l_remainder = Y_candidate mod 10^l
            long long pow_l = 1;
            for (int i = 0; i < l; ++i) pow_l *= 10;
            long long l_remainder = Y_candidate % pow_l;

