    int equal_pos = input.find(" = ");
    if (equal_pos == string::npos) {
        cout << "Impossible";
        return 0;
    }
    string left_part = input.substr(0, equal_pos);
    string right_str = input.substr(equal_pos + 3);
    int target = stoi(right_str);

    vector<int> coefficients;
    vector<string> tokens;
    stringstream ss(left_part);
    string token;
    while (ss >> token) {
        tokens.push_back(token);
    }

    coefficients.push_back(1);
    int i = 1;
    while (i < tokens.size()) {
        if (tokens[i] == "+") {
            coefficients.push_back(1);
        } else if (tokens[i] == "-") {
            coefficients.push_back(-1);
        }
        i += 2;
    }

    int p = 0, q = 0;
    for (int c : coefficients) {
        if (c == 1) p++;
        else q++;
    }

    int current_sum = p * 1 - q * target;
    int delta_adj = target - current_sum;
    int available_plus = p * (target - 1);
    int available_minus = q * (target - 1);

    if (available_plus + available_minus < delta_adj) {
        cout << "Impossible";
        return 0;
    }

    vector<int> variables;
    for (int c : coefficients) {
        if (c == 1)
            variables.push_back(1);
        else
            variables.push_back(target);
    }

