#include <bits/stdc++.h>
using namespace std;

class SparseTable {
public:
    vector<vector<int>> st;
    vector<int> log_table;
    int size;

    SparseTable(const vector<int>& arr) {
        size = arr.size();
        if (size == 0) return;
        log_table.resize(size + 1);
        for (int i = 2; i <= size; ++i)
            log_table[i] = log_table[i >> 1] + 1;
        int k_max = log_table[size] + 1;
        st.resize(k_max);
        st[0] = arr;
        for (int k = 1; k < k_max; ++k) {
            int len = 1 << k;
            st[k].resize(size - len + 1);
            for (int i = 0; i < st[k].size(); ++i) {
                st[k][i] = max(st[k-1][i], st[k-1][i + (1 << (k-1))]);
            }
        }
    }

    int query(int l, int r) {
        int length = r - l + 1;
        int k = log_table[length];
        return max(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> a(n-1);
    for (int i = 0; i < n-1; ++i) {
        cin >> a[i];
    }

    if (n == 1) {
        cout << 0 << endl;
        return 0;
    }

    // Build sparse table
    SparseTable st(a);

    long long total_sum = 0;

    for (int i = 1; i <= n-1; ++i) {
        int current_start = i + 1;
        int current_end = a[i-1];
        long long sum_i = 0;
        if (current_start <= current_end) {
            sum_i += (current_end - i) * 1;
        }

        int steps = 1;

        while (current_end < n) {
            int next_start = current_end + 1;
            if (next_start > n) break;
            int L = current_start;
            int R = current_end;
            int l = L - 1;
            int r = R - 1;
            if (l > r) break;

            int max_in_range = st.query(l, r);
            int next_max = max_in_range;

            if (next_max <= current_end) break;

            steps++;
            int count = next_max - current_end;
            sum_i += (long long)count * steps;

            current_start = next_start;
            current_end = next_max;
        }

        total_sum += sum_i;
    }

    cout << total_sum << endl;
    return 0;
}

