    ll low = 1, high = 100000;
    while (low <= high) {
        ll mid = (low + high) / 2;
        ll cube = mid * mid * mid;
        if (cube == m) return mid;
        if (cube < m) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return high;
