#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    string n_str;
    cin >> n_str;

    int len = n_str.length();
    vector<char> n_digits(len);
    for (int i = 0; i < len; ++i) {
        n_digits[i] = n_str[i];
    }

    string result(len * 2, '0');

    // First half of the palindrome
    for (int i = 0; i < len; ++i) {
        result[i] = '0' + (n_digits[i] - '0');
    }

    // Second half is mirror of the first
    for (int i = 0; i < len; ++i) {
        result[len + i] = result[i];
    }

    cout << result << endl;

    return 0;
}

