string subtract_one(const string& num) {
    string s = num;
    int i = s.length() - 1;
    while (i >= 0 && s[i] == '0') {
        s[i] = '9';
        i--;
    }
    if (i < 0) return "0";
    s[i]--;
    return s;
}

string subtract_strings(const string& a, const string& b) {
    string res;
    int i = a.length() - 1, j = b.length() - 1;
    int borrow = 0;
    while (i >= 0 || j >= 0) {
        int digit_a = (i >= 0) ? (a[i] - '0') : 0;
        int digit_b = (j >= 0) ? (b[j] - '0') : 0;
        int diff = digit_a - digit_b - borrow;
        if (diff < 0) {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res.push_back('0' + diff);
        i--;
        j--;
    }
    reverse(res.begin(), res.end());
    int first_non_zero = 0;
    while (first_non_zero < res.length() && res[first_non_zero] == '0') first_non_zero++;
    if (first_non_zero == res.length()) return "0";
    return res.substr(first_non_zero);
}

string add_strings(const string& a, const string& b) {
    string res;
    int i = a.length() - 1, j = b.length() - 1;
    int carry = 0;
    while (i >= 0 || j >= 0 || carry > 0) {
        int digit_a = (i >= 0) ? (a[i] - '0') : 0;
        int digit_b = (j >= 0) ? (b[j] - '0') : 0;
        int sum = digit_a + digit_b + carry;
        carry = sum / 10;
        res.push_back('0' + (sum % 10));
        i--;
        j--;
    }
    reverse(res.begin(), res.end());
    int first_non_zero = 0;
    while (first_non_zero < res.length() && res[first_non_zero] == '0') first_non_zero++;
    if (first_non_zero == res.length()) return "0";
    return res.substr(first_non_zero);
}

