    graph[v].push_back({u, (int)graph[u].size() - 1, w});
}

long long dijkstra(int n, int s, int t) {
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    vector<long long> d(n, INF);
    d[s] = 0;
    pq.push({0, s});

    while (!pq.empty()) {
        long long dist_u = pq.top().first;
        int u = pq.top().second;
        pq.pop();

        if (d[u] < dist_u) continue;

        for (auto& e : graph[u]) {
            long long new_dist = d[u] + e.weight;
            if (d[e.to] > new_dist) {
                d[e.to] = new_dist;
                pq.push({new_dist, e.to});
            }
        }
    }

    return d[t];
}

