    int maxDistance = 0;
    int lastVowelPos = -1;

    for (int i = 0; i <= n; ++i) {
        if (i == n) {
            if (lastVowelPos != -1) {
                maxDistance = max(maxDistance, i - lastVowelPos);
            }
            break;
        }
        bool isVowel = false;
        for (char c : vowels) {
            if (s[i] == c) {
                isVowel = true;
                break;
            }
        }
        if (isVowel) {
            if (lastVowelPos != -1) {
                maxDistance = max(maxDistance, i - lastVowelPos);
            } else {
                maxDistance = max(maxDistance, i);
            }
            lastVowelPos = i;
        }
    }

    cout << maxDistance << endl;
    return 0;
}

