        build(0, 0, n-1, data);
    }

    void build(int node, int l, int r, const vector<long long>& data) {
        if (l == r) {
            tree[node] = {data[l]};
            return;
        }
        int mid = (l + r) / 2;
        build(2*node+1, l, mid, data);
        build(2*node+2, mid+1, r, data);
