        }
        int mid = (l + r) / 2;
        build(2*node, l, mid, keys);
        build(2*node+1, mid+1, r, keys);
        tree[node] = merge(tree[2*node], tree[2*node+1]);
    }
    vector<int> merge(const vector<int>& a, const vector<int>& b) {
        vector<int> res;
