bool is_valid(int t, const vector<int>& crush, int n) {
    vector<bool> visited(n, false);
    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;
        map<int, int> path;
        int current = i;
        int step = 0;
        while (true) {
            if (visited[current]) {
                // Check if the cycle is consistent with t
                int cycle_len = path.size();
                int cycle_start = path[current];
                if (t % cycle_len != 0) return false;
                for (int j = 0; j < cycle_len; ++j) {
                    int node = path.find(cycle_start + j)->second;
                    visited[node] = true;
                }
                break;
            }
            if (path.find(current) != path.end()) {
                // Found a cycle, check if t is valid
                int cycle_len = path.size() - path[current];
                if (t % cycle_len != 0) return false;
                for (auto& p : path) {
                    visited[p.first] = true;
                }
                break;
            }
            path[current] = step++;
            current = crush[current] - 1;
        }
    }
    return true;
}

