    int count = 0;
    int min_r = INT_MAX, max_r = -1, min_c = INT_MAX, max_c = -1;
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (grid[r][c] == 'X') {
                count++;
                min_r = min(min_r, r);
                max_r = max(max_r, r);
                min_c = min(min_c, c);
                max_c = max(max_c, c);
            }
        }
    }

    int h_b = max_r - min_r + 1;
    int w_b = max_c - min_c + 1;

    if (count == h_b * w_b) {
        cout << "YES" << endl;
        return 0;
    }

    // Precompute row and column sets
    vector<set<int>> row_cols(n);
    vector<set<int>> col_rows(m);
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (grid[r][c] == 'X') {
                row_cols[r].insert(c);
                col_rows[c].insert(r);
            }
        }
    }

