int main() {
    string a, b;
    cin >> a >> b;

    int n = a.size(), m = b.size();

    // Preprocess: for each character in a, store the positions where it occurs
    vector<vector<int>> pos(26);
    for (int i = 0; i < n; ++i) {
        pos[a[i] - 'a'].push_back(i);
    }

    // Find the longest prefix of b that is a subsequence of a
    int left = 0;
    for (int i = 0; i < m; ++i) {
        char c = b[i];
        int idx = -1;
        for (int j = left; j < pos[c - 'a'].size(); ++j) {
            if (pos[c - 'a'][j] > left) {
                idx = pos[c - 'a'][j];
                break;
            }
        }
        if (idx == -1) break;
        left = idx + 1;
    }

    // Find the longest suffix of b that is a subsequence of a
    int right = n - 1;
    for (int i = m - 1; i >= 0; --i) {
        char c = b[i];
        int idx = -1;
        for (int j = right; j >= 0; --j) {
            if (pos[c - 'a'][j] < right) {
                idx = pos[c - 'a'][j];
                break;
            }
        }
        if (idx == -1) break;
        right = idx - 1;
    }

    // Combine prefix and suffix
    string result;
    for (int i = 0; i < m; ++i) {
        if (i < left || i > right) {
            result += b[i];
        }
    }

    if (result.empty()) {
        cout << "-";
    } else {
        cout << result;
    }

    return 0;
}

