    int h_index = h - 1;
    int other_players = total_players - 1;
    int other_h_dept = s[h_index] - 1;

    // Total ways to choose team with Herr Wafa
    long long total_ways = 1;
    for (int i = 0; i < m; ++i) {
        if (i == h_index) {
            total_ways *= (long long)(s[i]);
        } else {
            total_ways *= (long long)(s[i] + 1);
        }
    }
    total_ways /= (long long)(n); // since we are choosing n-1 more players

