using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<char>> grid(n, vector<char>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> grid[i][j];
        }
    }

    vector<vector<bool>> visited(n, vector<bool>(m, false));
    vector<pair<int, int>> wolfPositions;
    vector<pair<int, int>> pigPositions;

    // Collect positions of wolves and pigs
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'W') {
                wolfPositions.push_back({i, j});
            } else if (grid[i][j] == 'P') {
                pigPositions.push_back({i, j});
            }
        }
    }

    // Directions: up, down, left, right
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    // BFS to find the maximum matching between pigs and wolves
    vector<int> matchPigToWolf(pigPositions.size(), -1);
    vector<int> matchWolfToPig(wolfPositions.size(), -1);

    // Function to find augmenting path using DFS
    bool dfs(int pigIdx, vector<vector<bool>>& visited) {
        visited[pigIdx] = true;
        for (int wolfIdx = 0; wolfIdx < wolfPositions.size(); ++wolfIdx) {
            if (matchPigToWolf[pigIdx] != wolfIdx && canEat(pigPositions[pigIdx], wolfPositions[wolfIdx], grid)) {
                if (matchWolfToPig[wolfIdx] == -1 || (!visited[matchWolfToPig[wolfIdx]] && dfs(matchWolfToPig[wolfIdx], visited))) {
                    matchPigToWolf[pigIdx] = wolfIdx;
                    matchWolfToPig[wolfIdx] = pigIdx;
                    return true;
                }
            }
        }
        return false;
    }

    // Check if a pig can be eaten by a wolf
    bool canEat(pair<int, int> pig, pair<int, int> wolf, vector<vector<char>>& grid) {
        int px = pig.first, py = pig.second;
        int wx = wolf.first, wy = wolf.second;
        if (abs(px - wx) + abs(py - wy) != 1) return false;
        return grid[px][py] == 'P' && grid[wx][wy] == 'W';
    }

    int result = 0;
    for (int i = 0; i < pigPositions.size(); ++i) {
        vector<bool> visited(pigPositions.size(), false);
        if (dfs(i, visited)) {
            ++result;
        }
    }

    cout << result << endl;
    return 0;
}

