    k--;
    for (int i = 0; i < n; ++i) {
        long long fact_n = 1;
        for (int j = 1; j <= n - i - 1; ++j) {
            fact_n *= j;
        }
        int idx = k / fact_n;
        k %= fact_n;
        swap(perm[i], perm[i + idx]);
    }

    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (isLucky(i + 1) && isLucky(perm[i])) {
