int main() {
    int n;
    cin >> n;
    vector<int> nums(n);
    for (int i = 0; i < n; ++i) {
        cin >> nums[i];
    }

    map<int, int> freq;
    for (int num : nums) {
        freq[num]++;
    }

    if (n == 3) {
        if (freq.size() == 3) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
        return 0;
    }

    // For n > 3, the frequencies should be:
    // - One number with frequency 2 (the middle one)
    // - All others have frequency 1, except possibly two numbers that can form a chain

    // Check if all numbers are consecutive
    sort(nums.begin(), nums.end());
    bool consecutive = true;
    for (int i = 1; i < n; ++i) {
        if (nums[i] - nums[i - 1] != 1) {
            consecutive = false;
            break;
        }
    }

    if (!consecutive) {
        cout << "NO" << endl;
        return 0;
    }

    // Check frequency counts
    if (freq.size() == 2) {
        // Two different numbers, must be in a circle like 1-2-1-2...
        // So each must appear exactly n/2 times
        if (n % 2 == 0 && (freq.begin()->second == n / 2)) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
        return 0;
    }

    if (freq.size() == 3) {
        // Middle number must have count 2, others 1 each
        int min_val = nums[0], max_val = nums[n - 1];
        int mid_val = min_val + 1;
        if (freq[min_val] == 1 && freq[mid_val] == 2 && freq[max_val] == 1) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
        return 0;
    }

    cout << "NO" << endl;
    return 0;
}

