    for (auto& [num, count] : freq) {
        if (count > 2) {
            cout << "NO";
            return 0;
        }
    }

    // If all numbers are the same, check if n is 1 or 2 (but n >= 3)
    if (freq.size() == 1) {
        cout << "NO";
        return 0;
    }

    // Check if the sequence can form a circle
    int min_val = nums[0];
    int max_val = nums.back();

    // For a valid circle, the difference between max and min should be 1 or 2
    if (max_val - min_val > 2) {
        cout << "NO";
        return 0;
    }

    // If difference is 2, then we must have exactly two elements at max and min
    if (max_val - min_val == 2) {
        if (freq[min_val] != 1 || freq[max_val] != 1) {
            cout << "NO";
            return 0;
        }
    }

    // If difference is 1, then the middle number must appear twice
    if (max_val - min_val == 1) {
        if (freq[min_val] != 1 || freq[max_val] != 1) {
            cout << "NO";
            return 0;
        }
    }

    cout << "YES";
    return 0;
}

