using namespace std;

int main() {
    string s;
    cin >> s;
    set<string> result;

    // For each '?', we can replace it with either '0' or '1'
    // We need to generate all possible combinations of 0 and 1 for '?'s
    // But since the length can be up to 105, generating all possibilities is not feasible directly

    // Instead, we simulate the game for each possible configuration
    // However, this is computationally infeasible for large number of '?'
    // Therefore, we use a recursive approach with memoization to explore all possibilities efficiently

    // Since the problem asks for the set of outcomes for all possible initial configurations,
    // and considering the constraints, we must find an optimized way to compute the set of possible outcomes.

    // Let's consider that the final two cards are determined by the choices made during the game.
    // The players remove one card at a time until only two remain.
    // Masha (first player) wants to minimize the binary number formed by the last two cards.
    // Petya (second player) wants to maximize it.

    // This is a game theory problem with optimal play from both sides.
    // To solve this, we can use dynamic programming where dp[l][r] represents the best outcome (min or max)
    // when the current segment is from index l to r.

    // We define a function that returns the best outcome (as a pair of characters) for a given range [l, r]
    // depending on whose turn it is.

    // Let's implement this approach:

    int n = s.length();
    vector<vector<pair<char, char>>> dp(n, vector<pair<char, char>>(n));

    function<pair<char, char>(int, int, bool)> dfs = [&](int l, int r, bool isMashaTurn) -> pair<char, char> {
        if (l + 1 == r) return {s[l], s[r]};
        if (dp[l][r].first != '\0') return dp[l][r];

        pair<char, char> best;
        if (isMashaTurn) {
            best = {'1', '1'};
            for (int i = l; i < r; ++i) {
                auto res = dfs(l, i - 1, false);
                res.first = s[i];
                res.second = dfs(i + 1, r, false).second;
                if (res < best) best = res;
            }
        } else {
            best = {'0', '0'};
            for (int i = l; i < r; ++i) {
                auto res = dfs(l, i - 1, true);
                res.first = s[i];
                res.second = dfs(i + 1, r, true).second;
                if (res > best) best = res;
            }
        }

        dp[l][r] = best;
        return best;
    };

    // Now, we need to handle the '?' characters. Since they can be 0 or 1, we have to try all combinations
    // but for large inputs, this is not feasible directly. So we use a recursive backtracking approach
    // to generate all possible replacements for '?' and compute the final outcome for each.

    // We'll use a recursive function to generate all possibilities and store the results in a set

    vector<int> questionMarks;
    for (int i = 0; i < n; ++i) {
