#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> heights(n);
    for (int i = 0; i < n; ++i) {
        cin >> heights[i];
    }

    // Find the index of the maximum height
    int maxIndex = 0;
    for (int i = 1; i < n; ++i) {
        if (heights[i] > heights[maxIndex]) {
            maxIndex = i;
        }
    }

    // Find the index of the minimum height, making sure it's after the max if they are the same
    int minIndex = n - 1;
    for (int i = n - 2; i >= 0; --i) {
        if (heights[i] < heights[minIndex]) {
            minIndex = i;
        }
    }

    // If the minimum is before the maximum, adjust the count
    if (minIndex < maxIndex) {
        minIndex++;
    }

    cout << minIndex << endl;
    return 0;
}

