#include <cctype>

int main() {
    std::string text;
    std::getline(std::cin, text);

    std::string result;
    bool afterPunctuation = false;

    for (size_t i = 0; i < text.length(); ++i) {
        char c = text[i];

        if (std::isalpha(c)) {
            if (afterPunctuation) {
                result += ' ';
                afterPunctuation = false;
            }
            result += c;
        } else if (c == ' ') {
            // Skip multiple spaces
            continue;
        } else { // Punctuation: '.', ',', '!', '?'
            result += c;
            afterPunctuation = true;
        }
    }

    std::cout << result << std::endl;
    return 0;
}

