    vector<vector<int>> results(m, vector<int>(k, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < k; ++j) {
            char a = A[i], b = B[j];
            if (a == b) {
                results[i][j] = 0; // Draw
            } else if ((a == 'R' && b == 'S') || (a == 'S' && b == 'P') || (a == 'P' && b == 'R')) {
                results[i][j] = 1; // A wins, B gets a spot
            } else {
                results[i][j] = -1; // B wins, A gets a spot
            }
        }
    }

    // Calculate total number of rounds each sequence cycles through
    long long full_cycles_A = n / m;
    long long full_cycles_B = n / k;
    long long remaining_rounds = n % m;

    // Count the number of wins for each player in one full cycle of both sequences
    int winA = 0, winB = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < k; ++j) {
            if (results[i][j] == 1) winA++;
            else if (results[i][j] == -1) winB++;
        }
    }

    // Multiply by full cycles
    long long total_winA = winA * full_cycles_A;
    long long total_winB = winB * full_cycles_B;

    // Now handle the remaining rounds
    for (int i = 0; i < remaining_rounds; ++i) {
        int a_idx = i % m;
        int b_idx = i % k;
        if (results[a_idx][b_idx] == 1) total_winA++;
        else if (results[a_idx][b_idx] == -1) total_winB++;
    }

