    vector<vector<int>> win_counts(m, vector<int>(k, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < k; ++j) {
            char a = A[i];
            char b = B[j];
            if ((a == 'R' && b == 'S') || (a == 'S' && b == 'P') || (a == 'P' && b == 'R')) {
                win_counts[i][j] = 1; // Nikephoros wins
            } else if (a != b) {
                win_counts[i][j] = -1; // Polycarpus wins
            }
        }
    }

    // Compute total wins in one full cycle of both sequences
    int total_nik_win = 0;
    int total_poly_win = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < k; ++j) {
            if (win_counts[i][j] == 1) total_nik_win++;
            else if (win_counts[i][j] == -1) total_poly_win++;
        }
    }

    long long full_cycles = n / (m * k);
    long long remaining_rounds = n % (m * k);

    long long nik_total = full_cycles * total_nik_win;
    long long poly_total = full_cycles * total_poly_win;

    // Process remaining rounds
    for (int round = 0; round < remaining_rounds; ++round) {
        int a_idx = round % m;
        int b_idx = round % k;
