    cin >> t;
    vector<long long> p(t);
    for (int i = 0; i < t; ++i) {
        cin >> p[i];
    }

    // Sort figures by cost in descending order
    sort(figures.begin(), figures.end(), [](const pair<long long, int>& a, const pair<long long, int>& b) {
        return a.second > b.second;
    });

    long long totalPoints = 0;
    long long destroyed = 0;
    int factor = 1;

    for (const auto& fig : figures) {
        long long k = fig.first;
        int c = fig.second;

        while (k > 0) {
            // Determine how many figures can be destroyed at current factor
            long long nextP = (factor <= t) ? p[factor - 1] : LLONG_MAX;
            long long maxToDestroy = min(k, nextP - destroyed);

            totalPoints += maxToDestroy * factor * c;
            destroyed += maxToDestroy;
            k -= maxToDestroy;

            if (destroyed == nextP && factor <= t) {
                factor++;
            }
        }
    }

    cout << totalPoints << endl;
    return 0;
}

