#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

unordered_map<int, int> memo;

int maxResult(int n) {
    if (n == 1) return 1;
    if (memo.find(n) != memo.end()) return memo[n];

    int maxSum = 0;
    for (int a = 2; a * a <= n; ++a) {
        if (n % a == 0) {
            int b = n / a;
            maxSum = max(maxSum, n + maxResult(b));
        }
    }

    memo[n] = maxSum;
    return maxSum;
}

int main() {
    int n;
    cin >> n;
    cout << maxResult(n) << endl;
    return 0;
}

