#include <iostream>
using namespace std;

const int MOD = 1000000007;

long long modpow(long long base, long long exp, long long mod) {
    long long result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp = exp / 2;
    }
    return result;
}

int main() {
    long long n;
    cin >> n;
    if (n == 0) {
        cout << 1 << endl;
        return 0;
    }
    long long a = modpow(2, 2 * n, MOD);
    long long b = modpow(3, n, MOD);
    long long res = (a * b) % MOD;
    cout << res << endl;
    return 0;
}

