// Function to compute matrix exponentiation
vector<vector<long long>> mat_mult(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int size = a.size();
    vector<vector<long long>> result(size, vector<long long>(size, 0));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            for (int k = 0; k < size; ++k) {
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    return result;
}

// Function to compute matrix power using binary exponentiation
vector<vector<long long>> mat_pow(const vector<vector<long long>>& matrix, long long power) {
    int size = matrix.size();
    vector<vector<long long>> result(size, vector<long long>(size, 0));
    for (int i = 0; i < size; ++i) {
        result[i][i] = 1;
    }
    while (power > 0) {
        if (power % 2 == 1) {
            result = mat_mult(result, matrix);
        }
        matrix = mat_mult(matrix, matrix);
        power /= 2;
    }
    return result;
}

int main() {
    long long n;
    cin >> n;
    if (n == 0) {
        cout << 1 << endl;
        return 0;
