#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    if (n < 3) {
        cout << 0 << endl;
        return 0;
    }

    vector<long long> prefix(n, 0);
    prefix[0] = a[0];
    for (int i = 1; i < n; ++i) {
        prefix[i] = prefix[i - 1] + a[i];
    }

    long long total = prefix[n - 1];
    if (total % 3 != 0) {
        cout << 0 << endl;
        return 0;
    }

    long long target = total / 3;
    long long sum = 0;
    int count = 0;

    for (int i = 1; i < n - 1; ++i) {
        sum += a[i - 1];
        if (sum == target) {
            long long mid_sum = 0;
            for (int j = i + 1; j < n; ++j) {
                mid_sum += a[j];
                if (mid_sum == target) {
                    count++;
                    break;
                }
            }
        }
    }

    cout << count << endl;
    return 0;
}

