using namespace std;

const int MAXN = 701;
long long dp[MAXN][MAXN];
vector<vector<int>> tree;

void dfs(int u, int parent, int& n) {
    dp[u][1] = 1;
    for (int v : tree[u]) {
        if (v == parent) continue;
        dfs(v, u, n);
        for (int i = n; i >= 1; --i) {
            for (int j = 1; j <= i; ++j) {
                dp[u][i] = max(dp[u][i], dp[u][j] * dp[v][i - j]);
            }
        }
    }
}

