const int MAXN = 701;
int n;
vector<vector<int>> adj;
long long dp[MAXN][MAXN]; // dp[u][k] = max product for subtree rooted at u with size k

void dfs(int u, int parent) {
    vector<int> children;
    for (int v : adj[u]) {
        if (v != parent) {
            dfs(v, u);
            children.push_back(v);
        }
    }

    // Initialize dp[u][1] = 1 (only itself)
    dp[u][1] = 1;

    // Merge children into current node's dp
    for (int child : children) {
        vector<long long> new_dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            if (dp[u][i] == 0) continue;
            for (int j = 1; j <= n - i; ++j) {
                if (dp[child][j] == 0) continue;
                new_dp[i + j] = max(new_dp[i + j], dp[u][i] * dp[child][j]);
            }
            // Also consider not merging the child's subtree
            new_dp[i] = max(new_dp[i], dp[u][i]);
        }
        for (int i = 1; i <= n; ++i) {
            dp[u][i] = new_dp[i];
        }
    }
}

