using namespace std;

int main() {
    int m;
    cin >> m;
    vector<int> q(m);
    for (int i = 0; i < m; ++i) {
        cin >> q[i];
    }
    int min_q = *min_element(q.begin(), q.end());

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    sort(a.begin(), a.end(), greater<int>());

    long long total = 0;
    int i = 0;
    while (i < n) {
        int cnt = 0;
        int j = i;
        while (j < i + min_q && j < n) {
            ++cnt;
            ++j;
        }
        for (int k = i; k < i + cnt; ++k) {
            total += a[k];
        }
        i += cnt;
        int free = min(2, n - i);
        i += free;
    }

    cout << total << endl;
    return 0;
}

