    vector<int> q(m);
    for (int i = 0; i < m; ++i) {
        cin >> q[i];
    }
    int min_q = *min_element(q.begin(), q.end());

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    sort(a.begin(), a.end(), greater<int>());

    long long total = 0;
    int i = 0;
    while (i < n) {
        int count = 0;
        int j = i;
        while (j < i + min_q && j < n) {
            ++count;
            ++j;
        }
        for (int k = 0; k < count; ++k) {
            total += a[i + k];
        }
        i += min_q;
        // Take up to two free items
