    int presses[3][3];
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            cin >> presses[i][j];
        }
    }

    char grid[3][3];
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int count = presses[i][j];
            // Check adjacent cells
            if (i > 0) count += presses[i - 1][j];
            if (i < 2) count += presses[i + 1][j];
            if (j > 0) count += presses[i][j - 1];
            if (j < 2) count += presses[i][j + 1];
            grid[i][j] = (count % 2 == 0) ? '1' : '0';
        }
    }

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            cout << grid[i][j];
        }
        cout << endl;
    }

    return 0;
}

