#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<Point> nails(n);
    for (int i = 0; i < n; ++i) {
        cin >> nails[i].x >> nails[i].y;
    }

    vector<int> rods(m);
    for (int i = 0; i < m; ++i) {
        cin >> rods[i];
    }

    vector<int> result(n, -1);
    vector<bool> used(m, false);

    for (int i = 0; i < n; ++i) {
        int next = (i + 1) % n;
        int prev = (i - 1 + n) % n;

        // Calculate the length of the two segments connected to the current nail
        int len1 = abs(nails[i].x - nails[prev].x) + abs(nails[i].y - nails[prev].y);
        int len2 = abs(nails[next].x - nails[i].x) + abs(nails[next].y - nails[i].y);

        int required_len = len1 + len2;

        // Find a rod with this length
        for (int j = 0; j < m; ++j) {
            if (!used[j] && rods[j] == required_len) {
                result[i] = j + 1;
                used[j] = true;
                break;
            }
        }
    }

    bool possible = true;
    for (int i = 0; i < n; ++i) {
        if (result[i] == -1) {
            possible = false;
            break;
        }
    }

    if (!possible) {
        cout << "NO\n";
    } else {
        cout << "YES\n";
        for (int i = 0; i < n; ++i) {
            cout << result[i] << " ";
        }
        cout << "\n";
    }

    return 0;
}

