    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> seq = {0};
    long long sum = 0;
    int size = 1;

    for (int i = 0; i < n; ++i) {
        int type;
        cin >> type;

        if (type == 1) {
            int a, x;
            cin >> a >> x;
            for (int j = 0; j < a; ++j) {
                seq[j] += x;
            }
            sum += (long long)a * x;
        } else if (type == 2) {
            int k;
            cin >> k;
            seq.push_back(k);
            sum += k;
            ++size;
        } else if (type == 3) {
            sum -= seq.back();
            seq.pop_back();
            --size;
        }

        double avg = (double)sum / size;
        cout << fixed << setprecision(6) << avg << endl;
    }

    return 0;
}

