#include <iostream>
#include <cmath>

bool isPrimitiveRoot(int x, int p) {
    int phi = p - 1;
    for (int i = 1; i < p - 1; ++i) {
        int power = 1;
        for (int j = 0; j < i; ++j) {
            power = (power * x) % p;
        }
        if ((power - 1) % p == 0) {
            return false;
        }
    }
    return true;
}

int countPrimitiveRoots(int p) {
    int count = 0;
    for (int x = 2; x < p; ++x) {
        if (isPrimitiveRoot(x, p)) {
            ++count;
        }
    }
    return count;
}

int main() {
    int p;
    std::cin >> p;
    std::cout << countPrimitiveRoots(p) << std::endl;
    return 0;
}

