#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    if (k == 1) {
        if (n == 1) {
            cout << "a" << endl;
        } else {
            cout << -1 << endl;
        }
        return 0;
    }

    if (k > n || (k == 2 && n == 1)) {
        cout << -1 << endl;
        return 0;
    }

    string result(n, ' ');
    char current = 'a';
    char next = 'b';

    for (int i = 0; i < n; ++i) {
        if (i < k) {
            result[i] = current;
            current += 2;
            if (current > 'z') current = 'a' + 1;
        } else {
            result[i] = next;
            next += 2;
            if (next > 'z') next = 'a' + 1;
        }
    }

    // Check if the string is valid (no adjacent duplicates)
    for (int i = 0; i < n - 1; ++i) {
        if (result[i] == result[i + 1]) {
            cout << -1 << endl;
            return 0;
        }
    }

    cout << result << endl;
    return 0;
}

