#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<pair<int, int>> stamps(n);
    for (int i = 0; i < n; ++i) {
        cin >> stamps[i].first >> stamps[i].second;
    }

    // Build adjacency list
    map<int, vector<int>> adj;
    for (const auto& [u, v] : stamps) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // Find the start node (degree 1)
    int start;
    for (const auto& [node, neighbors] : adj) {
        if (neighbors.size() == 1) {
            start = node;
            break;
        }
    }

    // Reconstruct the path
    vector<int> path;
    set<int> visited;
    int current = start;
    while (true) {
        path.push_back(current);
        visited.insert(current);
        int next = -1;
        for (int neighbor : adj[current]) {
            if (visited.find(neighbor) == visited.end()) {
                next = neighbor;
                break;
            }
        }
        if (next == -1) break;
        current = next;
    }

    for (int city : path) {
        cout << city << " ";
    }
    cout << endl;

    return 0;
}

