#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Interval {
    int l, r, idx;
};

bool compare(const Interval& a, const Interval& b) {
    return a.l < b.l || (a.l == b.l && a.r < b.r);
}

int main() {
    int n;
    cin >> n;
    vector<Interval> intervals(n);
    for (int i = 0; i < n; ++i) {
        cin >> intervals[i].l >> intervals[i].r;
        intervals[i].idx = i + 1;
    }

    sort(intervals.begin(), intervals.end(), compare);

    vector<int> result;
    int count = 0;

    for (int i = 0; i < n; ++i) {
        vector<Interval> temp = intervals;
        temp.erase(temp.begin() + i);

        bool valid = true;
        int prev_end = -1;
        for (const auto& interval : temp) {
            if (interval.l < prev_end) {
                valid = false;
                break;
            }
            prev_end = interval.r;
        }

        if (valid) {
            result.push_back(intervals[i].idx);
            ++count;
        }
    }

    cout << count << endl;
    if (count > 0) {
        sort(result.begin(), result.end());
        for (int num : result) {
            cout << num << " ";
        }
    }
    cout << endl;

    return 0;
}

