#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> h(n);
    for (int i = 0; i < n; ++i) {
        cin >> h[i];
    }

    long long result = 0;

    // For each hill, find the next greater to the left and right
    stack<int> s;
    vector<int> next_greater_left(n, -1);
    vector<int> next_greater_right(n, -1);

    // Next greater to the left
    for (int i = 0; i < n; ++i) {
        while (!s.empty() && h[s.top()] <= h[i]) {
            s.pop();
        }
        if (!s.empty()) {
            next_greater_left[i] = s.top();
        }
        s.push(i);
    }

    // Clear stack for next greater to the right
    s = stack<int>();

    // Next greater to the right
    for (int i = n - 1; i >= 0; --i) {
        while (!s.empty() && h[s.top()] <= h[i]) {
            s.pop();
        }
        if (!s.empty()) {
            next_greater_right[i] = s.top();
        }
        s.push(i);
    }

    // Count pairs
    for (int i = 0; i < n; ++i) {
        int left = next_greater_left[i];
        int right = next_greater_right[i];

        // Pairs with hills between left and i
        if (left != -1) {
            result += (i - left - 1);
        }

        // Pairs with hills between i and right
        if (right != -1) {
            result += (right - i - 1);
        }

        // Add the pair with the next greater on the left
        if (left != -1) {
            result += 1;
        }

        // Add the pair with the next greater on the right
        if (right != -1) {
            result += 1;
        }
    }

    // Each hill can see its neighbors, but we've counted them in the above logic
    // However, we need to add all adjacent pairs as they are always visible
    result += n;

    cout << result << endl;

    return 0;
}

