#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> perm(n);
    for (int i = 0; i < n; ++i) {
        cin >> perm[i];
    }

    vector<int> original(n);
    for (int i = 0; i < n; ++i) {
        original[i] = i + 1;
    }

    int l = -1, r = -1;

    // Find the first position where the permutation differs from original
    for (int i = 0; i < n; ++i) {
        if (perm[i] != original[i]) {
            l = i + 1; // convert to 1-based index
            break;
        }
    }

    // If the permutation is already correct, output 0 0
    if (l == -1) {
        cout << "0 0" << endl;
        return 0;
    }

    // Find the last position where the permutation differs from original
    for (int i = n - 1; i >= 0; --i) {
        if (perm[i] != original[i]) {
            r = i + 1; // convert to 1-based index
            break;
        }
    }

    // Reverse the segment [l, r] in the original array and check if it matches the given permutation
    vector<int> test = original;
    reverse(test.begin() + l - 1, test.begin() + r);

    if (test == perm) {
        cout << l << " " << r << endl;
    } else {
        cout << "0 0" << endl;
    }

    return 0;
}

