    int stowaway_pos;
    int controller_pos;
    int direction; // 0: to head, 1: to tail
    int time;
};

int main() {
    int n, m, k;
    string direction_str;
    string train_states;

    cin >> n >> m >> k;
    cin >> direction_str;
    cin >> train_states;

    int controller_dir = (direction_str == "to head") ? 0 : 1;

    queue<State> q;
    q.push({m, k, controller_dir, 0});

    vector<vector<vector<bool>>> visited(n + 1, vector<vector<bool>>(n + 1, vector<bool>(2, false)));

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        int stow = current.stowaway_pos;
        int contr = current.controller_pos;
        int dir = current.direction;
        int t = current.time;

        if (t >= train_states.length()) {
            cout << "Stowaway" << endl;
            return 0;
        }

        char state = train_states[t];

        if (state == '0') { // Train is moving
            // Stowaway moves first
            for (int ds = -1; ds <= 1; ++ds) {
                int new_stow = stow + ds;
                if (new_stow >= 1 && new_stow <= n) {
                    if (!visited[new_stow][contr][dir]) {
                        visited[new_stow][contr][dir] = true;
                        q.push({new_stow, contr, dir, t + 1});
                    }
                }
            }
            // Controller moves
            int new_contr;
            if (dir == 0) {
                new_contr = contr - 1;
                if (new_contr == 0) {
                    new_contr = 1;
                    dir = 1;
                }
            } else {
                new_contr = contr + 1;
                if (new_contr == n + 1) {
                    new_contr = n;
                    dir = 0;
                }
            }
            if (!visited[stow][new_contr][dir]) {
                visited[stow][new_contr][dir] = true;
                q.push({stow, new_contr, dir, t + 1});
            }
        } else { // Train is idle
            // Stowaway leaves the train
            // Controller moves
            int new_contr;
            if (dir == 0) {
                new_contr = contr - 1;
                if (new_contr == 0) {
                    new_contr = 1;
                    dir = 1;
                }
            } else {
                new_contr = contr + 1;
                if (new_contr == n + 1) {
                    new_contr = n;
                    dir = 0;
                }
            }
            // Stowaway re-enters the train in any wagon
            for (int i = 1; i <= n; ++i) {
                if (!visited[i][new_contr][dir]) {
                    visited[i][new_contr][dir] = true;
                    q.push({i, new_contr, dir, t + 1});
                }
            }
        }

        // Check if caught
        if (stow == contr) {
            cout << "Controller " << t + 1 << endl;
            return 0;
        }
    }

    cout << "Stowaway" << endl;
    return 0;
}

