    for (int i = 0; i < k; ++i) {
        int a, b;
        cin >> a >> b;
        wasteCells.insert({a, b});
    }

    for (int i = 0; i < t; ++i) {
        int x, y;
        cin >> x >> y;
        if (wasteCells.find({x, y}) != wasteCells.end()) {
            cout << "Waste";
        } else {
            int index = 0;
            for (int row = 1; row < x; ++row) {
                for (int col = 1; col <= m; ++col) {
                    if (wasteCells.find({row, col}) == wasteCells.end()) {
                        ++index;
                    }
                }
            }
            for (int col = 1; col < y; ++col) {
                if (wasteCells.find({x, col}) == wasteCells.end()) {
                    ++index;
                }
            }
            int mod = index % 3;
            if (mod == 0) {
                cout << "Carrots";
            } else if (mod == 1) {
                cout << "Kiwis";
            } else {
                cout << "Grapes";
            }
        }
        cout << endl;
    }

    return 0;
}

struct pair_hash {
    template <class T1, class T2>
    size_t operator()(const pair<T1, T2>& p) const {
        return hash<T1>()(p.first) ^ (hash<T2>()(p.second) << 1);
    }
};

