#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

long long reflection(long long n) {
    string s = to_string(n);
    for (char& c : s) {
        c = '9' - c;
    }
    // Remove leading zeros
    size_t firstNonZero = s.find_first_not_of('0');
    if (firstNonZero == string::npos) return 0; // all zeros
    return stoll(s.substr(firstNonZero));
}

long long maxWeight(int l, int r) {
    long long maxProd = 0;
    for (long long n = l; n <= r; ++n) {
        long long refl = reflection(n);
        long long prod = n * refl;
        if (prod > maxProd) {
            maxProd = prod;
        }
    }
    return maxProd;
}

int main() {
    int l, r;
    cin >> l >> r;
    cout << maxWeight(l, r) << endl;
    return 0;
}

