#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

using namespace std;

struct Fraction {
    long long numerator;
    long long denominator;

    Fraction(long long n, long long d) : numerator(n), denominator(d) {
        if (d < 0) {
            numerator = -n;
            denominator = -d;
        }
        long long g = gcd(abs(numerator), abs(denominator));
        numerator /= g;
        denominator /= g;
    }

    static long long gcd(long long a, long long b) {
        while (b) {
            long long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    Fraction operator+(const Fraction& other) const {
        long long new_num = numerator * other.denominator + other.numerator * denominator;
        long long new_den = denominator * other.denominator;
        return Fraction(new_num, new_den);
    }

    Fraction operator*(const Fraction& other) const {
        long long new_num = numerator * other.numerator;
        long long new_den = denominator * other.denominator;
        return Fraction(new_num, new_den);
    }
};

int main() {
    int n;
    cin >> n;

    vector<Fraction> e(n + 1);
    for (int i = 1; i <= n; ++i) {
        e[i] = Fraction(0, 1);
    }

    for (int k = n - 1; k >= 0; --k) {
        Fraction sum(0, 1);
        for (int i = 0; i < n; ++i) {
            if ((1 << i) > n) break;
            sum = sum + Fraction(1, 1) * Fraction(1, (1 << i));
        }
        e[k] = Fraction(1, 1) + Fraction(1, 2) * e[k + 1];
    }

    cout << e[0].numerator << "/" << e[0].denominator << endl;

    return 0;
}

