    // The pattern repeats every 3 moves: 0 -> 1 -> 2 -> 0 -> ...
    // We can simulate the process in reverse from the end to find the initial position
    for (long long i = n; i > 0; --i) {
        if (i % 2 == 1) {
            // Odd move: swap left (0) and middle (1)
            if (x == 0) x = 1;
            else if (x == 1) x = 0;
        } else {
            // Even move: swap middle (1) and right (2)
            if (x == 1) x = 2;
