#include <bits/stdc++.h>
using namespace std;

struct Ring {
    long long a, b, h;
};

bool compare(Ring r1, Ring r2) {
    if (r1.b != r2.b)
        return r1.b > r2.b;
    return r1.a < r2.a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<Ring> rings(n);
    for (int i = 0; i < n; ++i) {
        cin >> rings[i].a >> rings[i].b >> rings[i].h;
    }

    sort(rings.begin(), rings.end(), compare);

    vector<long long> dp(n, 0);
    vector<long long> max_h(n, 0);

    for (int i = 0; i < n; ++i) {
        dp[i] = rings[i].h;
        max_h[i] = rings[i].h;
        for (int j = 0; j < i; ++j) {
            if (rings[j].a < rings[i].b && rings[j].b >= rings[i].b) {
                if (dp[j] + rings[i].h > dp[i]) {
                    dp[i] = dp[j] + rings[i].h;
                    max_h[i] = max(max_h[i], max_h[j]);
                }
            }
        }
        max_h[i] = max(max_h[i], dp[i]);
    }

    long long result = 0;
    for (int i = 0; i < n; ++i) {
        result = max(result, max_h[i]);
    }

    cout << result << endl;

    return 0;
}

