using namespace std;

double poissonProb(int k, double lambda) {
    return exp(-lambda) * pow(lambda, k) / tgamma(k + 1);
}

double uniformProb(int k, int P) {
    if (k >= 0 && k <= 2 * P)
        return 1.0 / (2 * P + 1);
    else
        return 0.0;
}

int main() {
    int V;
    cin >> V;
    vector<vector<int>> villages(V, vector<int>(250));

    for (int i = 0; i < V; ++i) {
        for (int j = 0; j < 250; ++j) {
            cin >> villages[i][j];
        }
    }

    for (int i = 0; i < V; ++i) {
        vector<int> responses = villages[i];
        sort(responses.begin(), responses.end());

        // Estimate lambda for Poisson using sample mean
        double lambda = 0.0;
        for (int k : responses) {
            lambda += k;
        }
        lambda /= 250;

        // Estimate P for Uniform using max value
        int max_k = responses.back();
        int P = max_k / 2;

        // Compute log-likelihoods
        double logLikelihoodPoisson = 0.0;
        double logLikelihoodUniform = 0.0;

        for (int k : responses) {
            logLikelihoodPoisson += log(poissonProb(k, lambda));
            logLikelihoodUniform += log(uniformProb(k, P));
        }

        if (logLikelihoodPoisson > logLikelihoodUniform)
            cout << "poisson" << endl;
        else
            cout << "uniform" << endl;
    }

    return 0;
}

