double poissonProb(int k, double lambda) {
    if (k < 0) return 0.0;
    double prob = exp(-lambda);
    for (int i = 1; i <= k; ++i) {
        prob *= lambda / i;
    }
    return prob;
}

double uniformProb(int k, int a, int b) {
    if (k < a || k > b) return 0.0;
    return 1.0 / (b - a + 1);
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        int N, P;
        cin >> N >> P;
        vector<int> responses(N);
        for (int i = 0; i < N; ++i) {
            cin >> responses[i];
        }

        // Adjust responses by adding back P
        for (int& r : responses) {
            r += P;
        }

        // Compute statistics
        double mean = 0.0;
        double variance = 0.0;
        for (int r : responses) {
            mean += r;
        }
        mean /= N;
        for (int r : responses) {
            variance += (r - mean) * (r - mean);
        }
        variance /= N;

        // Poisson distribution has variance equal to mean
        // Uniform distribution has variance (b - a + 1)^2 - 1 / 12
        // Estimate a and b from data
        int minResp = *min_element(responses.begin(), responses.end());
        int maxResp = *max_element(responses.begin(), responses.end());

        double expectedUniformVariance = ((maxResp - minResp + 1) * (maxResp - minResp + 1) - 1) / 12.0;

        double diffPoisson = abs(variance - mean);
        double diffUniform = abs(variance - expectedUniformVariance);

        if (diffPoisson < diffUniform) {
            cout << "poisson" << endl;
        } else {
            cout << "uniform" << endl;
        }
    }
    return 0;
}

