#include <iostream>
#include <vector>
#include <map>
#include <cmath>
#include <algorithm>

using namespace std;

const double EPS = 1e-6;

double poissonProb(int k, double lambda) {
    if (lambda <= 0) return 0.0;
    double prob = exp(-lambda);
    for (int i = 1; i <= k; ++i) {
        prob *= lambda / i;
    }
    return prob;
}

double uniformProb(int k, int a, int b) {
    if (k < a || k > b) return 0.0;
    return 1.0 / (b - a + 1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    for (int t = 0; t < T; ++t) {
        int N, P;
        cin >> N >> P;
        vector<int> responses(N);
        for (int i = 0; i < N; ++i) {
            cin >> responses[i];
        }

        // Adjust responses by adding P
        for (int& r : responses) {
            r += P;
        }

        map<int, int> freq;
        for (int r : responses) {
            freq[r]++;
        }

        // Estimate lambda for Poisson
        double lambda = 0.0;
        for (auto [k, count] : freq) {
            lambda += static_cast<double>(count) * k;
        }
        lambda /= N;

        // Calculate expected frequencies under Poisson and Uniform
        map<int, double> poissonExpected;
        map<int, double> uniformExpected;

        int minResp = *min_element(responses.begin(), responses.end());
        int maxResp = *max_element(responses.begin(), responses.end());

        for (auto [k, count] : freq) {
            poissonExpected[k] = N * poissonProb(k, lambda);
        }

        for (auto [k, count] : freq) {
            uniformExpected[k] = N * uniformProb(k, minResp, maxResp);
        }

        // Compute chi-square statistics
        double chi2Poisson = 0.0;
        double chi2Uniform = 0.0;

        for (auto [k, count] : freq) {
            double e_poisson = poissonExpected[k];
            double e_uniform = uniformExpected[k];

            if (e_poisson > EPS) {
                chi2Poisson += ((count - e_poisson) * (count - e_poisson)) / e_poisson;
            } else {
                chi2Poisson += 0.0;
            }

            if (e_uniform > EPS) {
                chi2Uniform += ((count - e_uniform) * (count - e_uniform)) / e_uniform;
            } else {
