    for (int t = 0; t < T; ++t) {
        int N, P;
        cin >> N >> P;
        vector<int> responses(N);
        for (int i = 0; i < N; ++i) {
            cin >> responses[i];
        }

        // Adjust responses by adding back P
        for (int &r : responses) {
            r += P;
        }

        // Count frequencies
        map<int, int> freq;
        for (int r : responses) {
            freq[r]++;
        }

        // For uniform distribution, all values should be the same
        bool is_uniform = true;
        int first_key = -1;
        for (const auto &pair : freq) {
            if (first_key == -1) {
                first_key = pair.first;
            } else if (pair.first != first_key) {
                is_uniform = false;
                break;
            }
        }

        if (is_uniform) {
            cout << "uniform" << endl;
        } else {
            // For Poisson distribution, check if all values are non-negative integers
            bool is_poisson = true;
            for (int r : responses) {
                if (r < 0 || fmod(r, 1.0) != 0.0) {
                    is_poisson = false;
                    break;
                }
            }
            cout << (is_poisson ? "poisson" : "unknown") << endl;
        }
    }
    return 0;
}

