    double dy = a.y - b.y;
    double dist = sqrt(dx * dx + dy * dy);
    return dist + a.r <= b.r;
}

int main() {
    int n;
    cin >> n;
    vector<Circle> circles(n);
    for (int i = 0; i < n; ++i) {
        cin >> circles[i].x >> circles[i].y >> circles[i].r;
    }

    // Sort circles by radius in descending order
    sort(circles.begin(), circles.end(), [](const Circle& a, const Circle& b) {
        return a.r > b.r;
    });

    // Compute inclusion hierarchy
    vector<vector<int>> included(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i != j && isInside(circles[i], circles[j])) {
                included[i].push_back(j);
            }
        }
    }

    // Compute contribution of each circle when it's not included in any other
    vector<double> unique_areas(n, 0.0);
    for (int i = 0; i < n; ++i) {
        bool is_unique = true;
        for (int j = 0; j < n; ++j) {
            if (i != j && isInside(circles[j], circles[i])) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            unique_areas[i] = area(circles[i]);
        }
    }

    // For each circle, compute the area that is not covered by any smaller circle
    vector<double> effective_areas(n, 0.0);
    for (int i = 0; i < n; ++i) {
        double current_area = area(circles[i]);
        for (int j : included[i]) {
            current_area -= effective_areas[j];
        }
        effective_areas[i] = current_area;
    }

    // Now, we want to select a subset S of circles such that no two are in inclusion relation
    // This is equivalent to choosing an antichain in the poset defined by inclusion
    // We can use dynamic programming on the inclusion hierarchy

    // Build the inclusion tree
    vector<vector<int>> children(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i != j && isInside(circles[i], circles[j])) {
                children[i].push_back(j);
            }
        }
    }

    // DP[i] = maximum sum of areas from subtree rooted at i
    vector<double> dp(n, 0.0);

    for (int i = n - 1; i >= 0; --i) {
        dp[i] = effective_areas[i];
        for (int j : children[i]) {
            dp[i] += dp[j];
        }
    }

    // The answer is the maximum value of dp[i] where i is not contained in any other circle
    double max_sum = 0.0;
    for (int i = 0; i < n; ++i) {
