#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x;
    cin >> n >> x;

    vector<vector<pair<int, int>>> duration_cost; // duration -> list of (cost, end_day)
    for (int i = 0; i < n; ++i) {
        int l, r, cost;
        cin >> l >> r >> cost;
        int d = r - l + 1;
        duration_cost.push_back({d, cost, r});
    }

    map<int, vector<pair<int, int>>> left_map;
    map<int, vector<pair<int, int>>> right_map;

    for (auto& v : duration_cost) {
        int d = v[0], cost = v[1], end = v[2];
        if (d <= x) {
            left_map[d].push_back({cost, end});
        }
    }

    long long min_cost = LLONG_MAX;

    for (auto& [d1, list1] : left_map) {
        int d2 = x - d1;
        if (d2 < 0 || d2 > x) continue;
        if (left_map.find(d2) == left_map.end()) continue;

        for (auto& [cost1, end1] : list1) {
            for (auto& [cost2, end2] : left_map[d2]) {
                if (end1 < end2) {
                    min_cost = min(min_cost, (long long)cost1 + cost2);
                } else if (end2 < end1) {
                    min_cost = min(min_cost, (long long)cost1 + cost2);
                }
            }
        }
    }

    if (min_cost == LLONG_MAX) {
        cout << -1 << endl;
    } else {
        cout << min_cost << endl;
    }

    return 0;
}

