#include <iostream>
#include <vector>
#include <queue>
#include <map>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    map<int, queue<int>> pos;
    for (int i = 0; i < n; ++i) {
        pos[a[i]].push(i);
    }

    int count = 0;
    int current_pos = 0;
    int min_val = *min_element(a.begin(), a.end());

    while (!pos.empty()) {
        int val = min_val;
        queue<int> &q = pos[val];
        int idx = q.front();
        q.pop();

        if (idx >= current_pos) {
            count += (idx - current_pos + 1);
            current_pos = idx + 1;
        } else {
            count += (n - current_pos + idx + 1);
            current_pos = idx + 1;
        }

        pos.erase(val);
        if (!pos.empty()) {
            min_val = (*pos.begin()).first;
        }
    }

    cout << count << endl;
    return 0;
}

