    vector<long long> fact(n + 1, 1);
    for (int i = 2; i <= n; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }

    // Compute the number of valid seat assignments
    // Each passenger can be assigned any of the n seats
    // So total seat assignments is n^m
    long long seat_assignments = pow(n, m, MOD);

    // For each passenger, there are 2 choices of entrance
    // So total entrance choices is 2^m
    long long entrance_choices = 1;
    for (int i = 0; i < m; ++i) {
        entrance_choices = (entrance_choices * 2) % MOD;
    }

    // Total ways is product of seat assignments and entrance choices
