#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<bool> visited;
vector<double> expected;

void dfs(int u) {
    visited[u] = true;
    double sum = 0.0;
    int count = 0;
    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs(v);
            sum += expected[v];
            count++;
        }
    }
    if (count > 0) {
        expected[u] = 1.0 + (sum / count);
    } else {
        expected[u] = 0.0;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    adj.resize(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    visited.assign(n + 1, false);
    expected.assign(n + 1, 0.0);
    dfs(1);

    cout << fixed << setprecision(15) << expected[1] << endl;
    return 0;
}

